import numpy as np

def leaky_relu(X, alpha=0.01):
    out = np.zeros_like(X)
    for i in range(X.shape[0]):
        for j in range(X.shape[1]):
            out[i, j] = X[i, j] if X[i, j] > 0 else alpha * X[i, j]
    return out
